// ---------------- 组装导出 ----------------
const SEV_NAME = { 1: '严重', 2: '高危', 3: '中危', 4: '低危' };

function build(raw, level) {
  return raw.map((r, i) => ({
    id: `${level}-${String(i + 1).padStart(3, '0')}`,
    name: r[0],
    category: r[1],
    cve: r[2] || '',
    level,
    levelText: SEV_NAME[level],
    desc: r[3],
    fix: r[4],
    tags: (r[5] || '').split(',').map(s => s.trim()).filter(Boolean),
    source: '内置',
  }));
}

